duts.declaration:
TYPE ST_Recipe :
STRUCT
    recipeID : INT;
    ingredientType : INT;
    ingredientRatio : REAL;
    productionTemperature : REAL;
END_STRUCT
END_TYPE

pous.declaration:
FUNCTION_BLOCK RecipeMgmt
VAR_INPUT
    addRecipe : BOOL;
    deleteRecipe : BOOL;
    modifyRecipe : BOOL;
    queryRecipe : BOOL;
    recipeIn : ST_Recipe;
END_VAR
VAR_OUTPUT
    recipeAdded : BOOL;
    recipeDeleted : BOOL;
    recipeModified : BOOL;
    recipeQueryResult : ST_Recipe;
    error : BOOL;
    status : WORD;
END_VAR
VAR_IN_OUT
    recipe : ARRAY[1..10] OF ST_Recipe;
END_VAR
VAR
    i : INT;
    slot : INT;
    found : BOOL;
    addPrev : BOOL;
    delPrev : BOOL;
    modPrev : BOOL;
    qryPrev : BOOL;
END_VAR

pous.implementation:
recipeAdded := FALSE;
recipeDeleted := FALSE;
recipeModified := FALSE;
error := FALSE;
status := 0;
IF queryRecipe AND NOT qryPrev THEN
    found := FALSE;
    FOR i := 1 TO 10 DO
        IF recipe[i].recipeID = recipeIn.recipeID THEN
            recipeQueryResult := recipe[i];
            found := TRUE;
        END_IF
    END_FOR
    IF NOT found THEN
        error := TRUE;
        status := 16#8001;
    END_IF
END_IF
IF addRecipe AND NOT addPrev THEN
    found := FALSE;
    FOR i := 1 TO 10 DO
        IF recipe[i].recipeID = recipeIn.recipeID THEN
            found := TRUE;
        END_IF
    END_FOR
    IF found THEN
        error := TRUE;
        status := 16#8002;
    ELSE
        slot := 0;
        FOR i := 1 TO 10 DO
            IF recipe[i].recipeID = 0 AND slot = 0 THEN
                slot := i;
            END_IF
        END_FOR
        IF slot = 0 THEN
            error := TRUE;
            status := 16#8003;
        ELSE
            recipe[slot] := recipeIn;
            recipeAdded := TRUE;
        END_IF
    END_IF
END_IF
IF deleteRecipe AND NOT delPrev THEN
    found := FALSE;
    FOR i := 1 TO 10 DO
        IF recipe[i].recipeID = recipeIn.recipeID THEN
            recipe[i].recipeID := 0;
            found := TRUE;
            recipeDeleted := TRUE;
        END_IF
    END_FOR
    IF NOT found THEN
        error := TRUE;
        status := 16#8004;
    END_IF
END_IF
IF modifyRecipe AND NOT modPrev THEN
    found := FALSE;
    FOR i := 1 TO 10 DO
        IF recipe[i].recipeID = recipeIn.recipeID THEN
            recipe[i] := recipeIn;
            found := TRUE;
            recipeModified := TRUE;
        END_IF
    END_FOR
    IF NOT found THEN
        error := TRUE;
        status := 16#8005;
    END_IF
END_IF
addPrev := addRecipe;
delPrev := deleteRecipe;
modPrev := modifyRecipe;
qryPrev := queryRecipe;

pous.declaration:
PROGRAM PLC_PRG
VAR
    fb : RecipeMgmt;
    db : ARRAY[1..10] OF ST_Recipe;
END_VAR
